"""Render a portable HTML dashboard for a lifecycle study."""

import html
import json
from pathlib import Path


def write_dashboard(result, output_dir):
    payload = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    title = html.escape(result.get("scenario", "Lifecycle study"))
    template = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lifecycle study dashboard</title><style>
:root{color-scheme:light;--ink:#17231f;--muted:#60716a;--line:#dce5df;--paper:#f4f7f4;--green:#176b4d;--red:#a83b3b;--amber:#9b6511}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1420px;margin:auto;padding:26px}h1{font-size:30px;margin:0 0 5px}h2{font-size:21px;margin:0 0 13px}h3{font-size:16px;margin:12px 0 8px}.muted,.fine{color:var(--muted)}.fine{font-size:12px}.head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.links{display:flex;gap:7px;flex-wrap:wrap}a.btn,button{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:8px;padding:8px 11px;text-decoration:none;font:inherit;cursor:pointer}.call{border-left:4px solid var(--amber);background:#fff8e9;padding:14px;margin:17px 0;border-radius:5px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}.card,section{background:#fff;border:1px solid var(--line);border-radius:11px}.card{padding:14px}.label{font-size:12px;color:var(--muted)}.value{font-size:23px;font-weight:730}.note{font-size:12px;color:var(--muted)}section{padding:18px;margin:16px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.funnel{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.step{background:#eaf2ed;padding:12px;border-radius:8px}.step b{display:block;font-size:22px}.step span{display:block;font-size:12px;color:var(--muted)}.toolbar{display:flex;gap:8px;margin-bottom:9px}.toolbar input,.toolbar select{font:inherit;padding:8px;border:1px solid var(--line);border-radius:7px}table{border-collapse:collapse;width:100%;font-size:12px;background:#fff}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{position:sticky;top:0;background:#edf3ef;z-index:1}.scroll{overflow:auto;max-height:590px;border:1px solid var(--line);border-radius:7px}tr:hover td{background:#f6faf7}.positive{color:var(--green)}.negative{color:var(--red)}.details{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.detail{padding:9px;background:#f6f9f7;border-radius:7px;overflow-wrap:anywhere}.detail b{display:block;color:var(--muted);font-size:11px;text-transform:capitalize}.detail span{font-weight:650}.barrow{display:grid;grid-template-columns:90px 1fr 70px;gap:7px;align-items:center;font-size:11px;margin:4px 0}.track{height:10px;background:#edf1ee;border-radius:8px}.bar{height:100%;background:#3b9670;border-radius:8px}.bar.loss{background:#c66a62}details{border-top:1px solid var(--line);padding:10px 0}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8f6;padding:10px;border-radius:7px;font-size:11px}.footer{margin-top:20px;font-size:12px;color:var(--muted)}@media(max-width:900px){.cards{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:600px){main{padding:14px}.head{display:block}.links{margin-top:10px}.cards{grid-template-columns:repeat(2,1fr)}.funnel{grid-template-columns:repeat(2,1fr)}.details{grid-template-columns:1fr 1fr}}
</style></head><body><main><div class="head"><div><div class="label">HISTORICAL LIFECYCLE REPLAY</div><h1>50-purchase study</h1><div class="muted" id="subtitle"></div></div><div class="links"><a class="btn" href="report.md">Markdown report</a><a class="btn" href="account-lifecycle.csv">Account CSV</a><a class="btn" href="session-summary.csv">Session CSV</a><a class="btn" href="lifecycle-study.json">Full JSON</a></div></div>
<div class="call"><b>One replay, not a forecast.</b><br><span id="caveat"></span></div><div class="cards" id="cards"></div>
<section><h2>Lifecycle at a glance</h2><div class="funnel" id="funnel"></div><p class="fine" id="cashnote"></p></section><section><h2>Complete scorecard</h2><div class="scroll"><table><thead><tr><th>Stat</th><th>Value</th></tr></thead><tbody id="scorecard"></tbody></table></div></section><section><h2>Strategy rules and setup</h2><div id="strategyIntro"></div><div class="details" id="strategyDetails"></div><div id="strategyRules"></div><details><summary>All strategy parameters and runtime settings</summary><h3>Strategy parameters</h3><pre id="strategyParams"></pre><h3>Runtime settings</h3><pre id="runtimeSettings"></pre></details></section>
<div class="grid"><section><h2>Attempt results</h2><div class="toolbar"><input id="search" placeholder="Search attempts"><select id="filter"><option value="all">All outcomes</option><option>passed</option><option>breached</option><option>unfinished</option></select></div><div class="scroll"><table><thead><tr><th>#</th><th>Eval</th><th>Period</th><th>Eval P&amp;L</th><th>Trades</th><th>WR / RR</th><th>Funded</th><th>Funded days</th><th>Payouts / receipts</th><th>Live</th><th>Final</th></tr></thead><tbody id="attempts"></tbody></table></div><p class="fine">Durations count observed trading sessions. Expand account details below for stage-level metrics and full event traces.</p></section><section><h2>Source P&amp;L by session</h2><p class="fine">Underlying strategy results across observed source sessions, after the configured $1 round-trip commission assumption.</p><div id="chart"></div></section></div>
<section><h2>Account detail and audit trail</h2><div id="accountDetails"></div></section><div class="grid"><section><h2>Cash ledger</h2><div class="scroll"><table><thead><tr><th>Timestamp</th><th>Account</th><th>Event</th><th>Amount</th></tr></thead><tbody id="cash"></tbody></table></div><p class="fine">Cash receipts count as inflows; account balances and pending/requested payouts do not.</p></section><section><h2>Input validation</h2><div id="validation"></div></section></div>
<section><h2>Study policies</h2><div class="details" id="policies"></div><h3>Limitations and assumptions</h3><ul id="limitations"></ul><h3>Rule references and reproducibility</h3><div id="sources"></div></section><div class="footer">Generated from the lifecycle study output. The linked JSON and CSV files retain the complete underlying results.</div></main><script>
const D=__DATA__,esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>v==null?'N/A':(Number(v)<0?'−$':'$')+Math.abs(Number(v)).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),score=Object.fromEntries(D.scorecard||[]),el=id=>document.getElementById(id),detail=(k,v)=>`<div class="detail"><b>${esc(k.replaceAll('_',' '))}</b><span>${esc(v)}</span></div>`;
el('subtitle').textContent=`__TITLE__ · ${D.selected_period.first_observed_session}–${D.selected_period.last_observed_session} · ${D.selected_period.observed_session_count} sessions · ${D.selected_period.trade_count} trades`;
el('caveat').textContent=`Available history supports ${D.purchased_attempts} of ${D.requested_attempts} purchases: ${D.evaluation_outcomes.passed} passed, ${D.evaluation_outcomes.breached} breached, ${D.evaluation_outcomes.unfinished} unfinished. Payout receipts were ${money(D.funded_payout_receipts)}. This replay does not estimate repeated-cycle probabilities.`;
const cards=[['Net cash result',score['Net cash profit'],'Before unverified external fees'],['Purchases',`${D.purchased_attempts} / ${D.requested_attempts}`,'Available history ended before 50'],['Pass rate',score['Eval pass rate'],`${D.evaluation_outcomes.passed} passed`],['Funded accounts',D.funded_outcomes.activated,`${D.funded_outcomes.active||0} active · ${D.funded_outcomes.breached||0} breached`],['Payout receipts',money(D.funded_payout_receipts),`Live bonus ${money(D.live_bonus_receipts)}`]];el('cards').innerHTML=cards.map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="value ${String(x[1]).includes('-$')?'negative':''}">${esc(x[1])}</div><div class="note">${esc(x[2])}</div></div>`).join('');el('scorecard').innerHTML=(D.scorecard||[]).map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td></tr>`).join('');
const S=D.strategy||{},P=S.parameters||{};el('strategyIntro').innerHTML=`<p><b>${esc(S.name||'Strategy name unavailable')}</b> <span class="muted">(${esc(S.project_name||'')})</span></p><p>${esc(S.description||'Strategy description unavailable.')}</p><p class="fine">This describes the NinjaScript rules used to generate the logged trades. The lifecycle simulator replays those closed trades; it does not rerun or optimize the entry/exit logic. Prop evaluation and funded-account limits are a separate overlay.</p><p><a href="../../../NYOpenFairPriceStrategy.cs">View NinjaScript source</a> · <a href="../../../docs/project.md">Project strategy notes</a></p>`;el('strategyDetails').innerHTML=[['Instrument',S.instrument],['Bars',S.bars_period],['Trading hours',S.trading_hours_template],['NinjaTrader time zone',S.trading_hours_timezone],['Simulated size',S.simulated_size],['Source commission status',S.source_commission_mode],['Calculation mode',S.runtime_settings?.Calculate],['Fair-price anchor',`${P.OpenHour??'9'}:${String(P.OpenMinute??'30').padStart(2,'0')} open`],['Continuation / reversion windows',`${P.ContinuationMinutes??'—'} / ${P.ReversionMinutes??'—'} minutes`],['Default stop / target',`${P.StopPoints??'—'} / ${P.TargetPoints??'—'} points`],['Maximum entries / layering',`${P.MaxTradesPerSession??'—'} / ${P.AllowLayering??'—'}`],['Observed source window',`${D.selected_period.first_observed_session} – ${D.selected_period.last_observed_session}`],['Run ID',D.input_run_id]].map(z=>detail(...z)).join('');
el('strategyRules').innerHTML=`<div class="grid"><div class="detail"><h3>1 · Opening continuation</h3><p>At the configured ${P.OpenHour??9}:${String(P.OpenMinute??30).padStart(2,'0')} open, the bar open becomes fair price and the opening candle sets the initial direction. During minutes 1–${(P.ContinuationMinutes??15)-1}, a bullish opening candle can enter long after a bullish break of structure or bullish displacement; a bearish opening candle can enter short after a bearish break or displacement. Only one continuation entry is allowed per session.</p><p>A structure break is a close beyond the prior ${P.StructureLookback??5} bars’ high or low. Displacement requires the candle body to exceed the previous body by ${P.DisplacementMultiplier??1.2}× and combined wick share to be at most ${P.MaxWickPercent??20}% of its range. If the opening direction is invalidated by a break of the opposite opening extreme within the first ${P.ConfirmationBars??3} minutes, the continuation entry is disabled.</p></div><div class="detail"><h3>2 · Fair-price reversion</h3><p>From minute ${P.ContinuationMinutes??15} until minute ${(P.ReversionMinutes??90)-1}, look to fade extensions back toward the fair-price anchor. Above fair price, a bearish break of structure or qualifying bearish displacement can trigger a short; below fair price, bullish confirmation can trigger a long.</p><p>Price must be at least ${P.MinDistanceFromFair??10} points from fair price. Displacement is accepted only when the extension is no more than ${P.DisplacementOverrideDistance??38} points from fair price; a reversal-direction structure break can trigger without that displacement-distance condition. The configured target mode is ${esc(P.ReversionTargetMode??'unknown')}.</p></div><div class="detail"><h3>Risk and exits</h3><p>Each entry submits a protective stop and profit target. ATR(14) selects the actual distances: above 20 points, 50-point stop / 75-point target; from 7 through 20, ${P.StopPoints??25} / ${P.TargetPoints??37.5}; below 7, 16.5 / 24.75. With FixedPoints selected, the target is the dynamic target distance. Positions also exit at session close, 30 seconds before the configured close.</p><p>The rule cap is ${P.MaxTradesPerSession??4} entry submissions per session. Entries require a flat position because layering is ${P.AllowLayering?'enabled':'disabled'}.</p></div><div class="detail"><h3>Execution and data setup</h3><p>Runs on ${esc(S.instrument)} one-minute bars with ${esc(S.runtime_settings?.Calculate??'OnBarClose')} calculation. The saved Analyzer run used standard one-minute fill resolution, zero modeled slippage, commissions excluded in Analyzer, and no Tick Replay. Its logger reports commissions as unknown; the simulator separately assumes $1 per MNQ round trip.</p><p>The lifecycle study applies its own 25K LucidFlex rules after each completed trade. Those prop rules are not entry signals or part of the NinjaScript strategy.</p></div></div>`;el('strategyParams').textContent=JSON.stringify(S.parameters||{},null,2);el('runtimeSettings').textContent=JSON.stringify(S.runtime_settings||{},null,2);
const funded=(D.accounts||[]).filter(a=>a.stage==='funded'),fundedCount=new Set(funded.map(a=>a.attempt)).size,payoutAccounts=funded.filter(a=>a.payout_count>0).length,liveCount=new Set((D.accounts||[]).filter(a=>a.stage==='live').map(a=>a.attempt)).size;el('cards').innerHTML=cards.map((x,i)=>i===3?`<div class="card"><div class="label">Funded accounts</div><div class="value">${fundedCount}</div><div class="note">${D.funded_outcomes.active||0} active · ${D.funded_outcomes.unfinished||0} unfinished</div></div>`:`<div class="card"><div class="label">${esc(x[0])}</div><div class="value ${String(x[1]).includes('-$')?'negative':''}">${esc(x[1])}</div><div class="note">${esc(x[2])}</div></div>`).join('');el('funnel').innerHTML=[['Purchases',D.purchased_attempts,`of ${D.requested_attempts} target`],['Passed',D.evaluation_outcomes.passed,'evaluation target met'],['Funded',fundedCount,'accounts activated'],['Payout',payoutAccounts,'funded accounts with receipts'],['Live',liveCount,'modeled live accounts']].map(x=>`<div class="step"><span>${esc(x[0])}</span><b>${esc(x[1])}</b><span>${esc(x[2])}</span></div>`).join('');el('cashnote').textContent=`Cash reconciliation: ${D.cash_ledger_reconciliation?.status||'see JSON'}. Evaluation fees: ${money(D.known_external_costs_net_of_refunds)}. Net cash equals modeled receipts less known external costs.`;
const attempts=D.attempt_summaries||[];function draw(){let q=el('search').value.toLowerCase(),f=el('filter').value;el('attempts').innerHTML=attempts.filter(a=>(f==='all'||a.evaluation_status===f)&&JSON.stringify(a).toLowerCase().includes(q)).map(a=>`<tr><td>${a.attempt}</td><td>${esc(a.evaluation_status)}</td><td>${esc(a.evaluation_start_session)}–${esc(a.evaluation_end_session)}</td><td>${money(a.evaluation_profit)}</td><td>${a.evaluation_trade_count}</td><td>${esc(a.evaluation_win_rate)} / ${esc(a.evaluation_reward_risk)}</td><td>${esc(a.funded_status)}</td><td>${esc(a.funded_duration_sessions??'—')}</td><td>${a.payout_count} / ${money(a.payout_receipts)}</td><td>${esc(a.live_status)}</td><td>${esc(a.final_status)}</td></tr>`).join('')||'<tr><td colspan="11">No matching attempts.</td></tr>'}el('search').addEventListener('input',draw);el('filter').addEventListener('change',draw);draw();
const sessions=D.source_session_summary||[],max=Math.max(1,...sessions.map(s=>Math.abs(+s.net_pnl)));el('chart').innerHTML=sessions.map(s=>{let n=+s.net_pnl;return `<div class="barrow"><span>${esc(s.session_id)}</span><div class="track"><div class="bar ${n<0?'loss':''}" style="width:${Math.max(1,Math.abs(n)/max*100)}%"></div></div><span class="${n<0?'negative':'positive'}">${money(n)}</span></div>`}).join('');
const groups={};for(const a of D.accounts||[])(groups[a.attempt]??=[]).push(a);el('accountDetails').innerHTML=attempts.map(a=>`<details><summary>Attempt ${a.attempt}: ${esc(a.evaluation_status)} · funded ${esc(a.funded_status)} · ${esc(a.final_status)}</summary>${(groups[a.attempt]||[]).map(x=>`<div><h3>${esc(x.stage)} · ${esc(x.status)} · ${esc(x.account_id)}</h3><div class="details">${[['Net P&L',money(x.net_pnl)],['Ending balance',money(x.balance)],['Loss floor',money(x.loss_floor)],['Trades',x.trade_count],['Wins / losses / flat',`${x.wins} / ${x.losses} / ${x.breakevens}`],['Win rate / realized RR',`${x.win_rate} / ${x.realized_reward_risk??'N/A'}`],['Average win / loss',`${money(x.average_win)} / ${money(x.average_loss)}`],['Gross P&L / commissions',`${money(x.gross_pnl)} / ${money(x.commissions)}`],['Start / end session',`${x.start_session??'—'} / ${x.end_session??'—'}`],['Duration',`${x.duration_trading_sessions??'—'} sessions`],['Qualifying days / payout count',`${x.qualifying_days_current_cycle} / ${x.payout_count}`],['Terminal reason',x.terminal_reason??'—']].map(z=>detail(...z)).join('')}</div>${x.payouts?.length?`<h3>Payout detail</h3><pre>${esc(JSON.stringify(x.payouts,null,2))}</pre>`:''}<details><summary>Full event trace (${(x.events||[]).length})</summary><pre>${esc(JSON.stringify(x.events||[],null,2))}</pre></details></div>`).join('')||'<p class="fine">No account records for this attempt.</p>'}</details>`).join('');
el('cash').innerHTML=(D.cash_ledger||[]).map(x=>`<tr><td>${esc(x.timestamp)}</td><td>${esc(x.account_id)}</td><td>${esc(x.type)}</td><td class="${+x.amount<0?'negative':'positive'}">${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="4">No cash events.</td></tr>';
const v=D.validation||{};el('validation').innerHTML='<div class="details">'+[['Status',v.status],['Run ID',v.run_id],['Validated trades',v.trade_count],['Executions / equity observations',`${v.execution_count} / ${v.equity_observations}`],['Analyzer gross / net',`${money(v.gross_pnl)} / ${money(v.analyzer_net_pnl)}`],['Assumed commissions',money(v.assumed_commissions_full_run)],['Net over full source under cost assumption',money(v.net_pnl_under_fixed_cost_assumption_full_run)]].map(z=>detail(...z)).join('')+'</div>';
el('policies').innerHTML=Object.entries(D.policies||{}).map(([k,v])=>detail(k,v)).join('');el('limitations').innerHTML=(D.limitations||[]).map(x=>`<li>${esc(x)}</li>`).join('');el('sources').innerHTML='<ul>'+Object.entries(D.rule_sources||{}).map(([k,v])=>`<li><a href="${esc(v)}" target="_blank" rel="noreferrer">${esc(k)} rules</a></li>`).join('')+'</ul><div class="fine">Input hashes<br>'+Object.entries(D.input_hashes||{}).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')+'<br>Code hashes<br>'+Object.entries(D.model_code_hashes||{}).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')+'</div>';
</script></body></html>'''
    document = template.replace("__DATA__", payload).replace("__TITLE__", title)
    output = Path(output_dir) / "dashboard.html"
    output.write_text(document, encoding="utf-8")
    return output
